import{z as d,x as c,o as i,c as p,q as n,j as o,D as e,d as r,s,S as E,b as t}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"符号执行 KLEE","description":"","frontmatter":{"title":"符号执行 KLEE","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/symbolic-execution.md","filePath":"cs/symbolic-execution.md","lastUpdated":1791413859000}'),B={name:"cs/symbolic-execution.md"};function u(m,a,A,f,h,D){const l=c("Mermaid");return i(),p("div",null,[a[2]||(a[2]=n('<h1 id="符号执行-klee" tabindex="-1">符号执行 KLEE <a class="header-anchor" href="#符号执行-klee" aria-label="Permalink to &quot;符号执行 KLEE&quot;">​</a></h1><div class="epigraph"><p>把输入当成符号，路径谓词交给 SMT，求解器吐出能走这条路径的具体字节。KLEE 在 LLVM 上这样找崩溃与断言失败；路径爆炸是它的税。</p><footer>—— Cadar, Dunbar and Engler, KLEE, OSDI 2008；King, Symbolic Execution, 1976</footer></div><p>上一课<a href="/cs/coverage-guided-fuzzing">fuzz</a>随机走。缺口是<strong>精确满足分支条件</strong>。主干<a href="/cs/smt-solver">SMT</a>已有求解器。本课把符号执行接到测试生成，不重推 SMT。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>fuzz 难猜 magic number。符号执行：每条分支加约束，<code>unsat</code> 则剪。缺口是循环与状态空间；混合（concolic）用具体跑加符号补。环境建模（系统调用）是工程。</p><p><span class="marginnote">「magic number」就是藏在比较里的魔法常量，比如 if (x == 0x5A4D)。fuzz 靠瞎撞几乎猜不中 16 位十六进制；符号执行把它变成方程 x = 0x5A4D，求解器一步解出——这是两者的分水岭。</span></p><h3 id="不是证明无洞" tabindex="-1">不是证明无洞 <a class="header-anchor" href="#不是证明无洞" aria-label="Permalink to &quot;不是证明无洞&quot;">​</a></h3><p>没扫到的路径沉默。与 fuzz、审计互补。</p><p><span class="marginnote">King 1976；KLEE OSDI 2008。本课不把求解器当攻击工具教程。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照具体执行与符号状态。指出与覆盖 fuzz 混合：求解器解卡住的比较。下一课静态污点：不跑程序也追踪数据流。</p>',12)),(i(),o(E,null,{default:e(()=>[s(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYM%5B%22%E7%AC%A6%E5%8F%B7%E8%BE%93%E5%85%A5%22%5D%20--%3E%20BR%5B%22%E5%88%86%E6%94%AF%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20BR%20--%3E%20SMT%5B%22SMT%22%5D%0A%20%20SMT%20--%3E%20IN%5B%22%E5%85%B7%E4%BD%93%E8%BE%93%E5%85%A5%22%5D%0A%20%20IN%20--%3E%20TEST%5B%22%E5%9B%9E%E5%BD%92%E7%94%A8%E4%BE%8B%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[r("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"发现手段在「动态随机 / 动态符号 / 静态」之间权衡。下一课静态与污点分析。",-1)),(i(),o(E,null,{default:e(()=>[s(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E5%87%BD%E6%95%B0%EF%BC%9A%E4%B8%A4%E4%B8%AA%E7%8B%AC%E7%AB%8B%20if%22%5D%20--%3E%20I1%5B%22if%201%20%E5%88%86%E5%8F%89%22%5D%0A%20%20I1%20--%3E%20T1%5B%22true%22%5D%0A%20%20I1%20--%3E%20F1%5B%22false%22%5D%0A%20%20T1%20--%3E%20I2%5B%22if%202%20%E5%88%86%E5%8F%89%22%5D%0A%20%20F1%20--%3E%20I3%5B%22if%202%20%E5%88%86%E5%8F%89%22%5D%0A%20%20I2%20--%3E%20P1%5B%22%E8%B7%AF%E5%BE%84%201%22%5D%0A%20%20I2%20--%3E%20P2%5B%22%E8%B7%AF%E5%BE%84%202%22%5D%0A%20%20I3%20--%3E%20P3%5B%22%E8%B7%AF%E5%BE%84%203%22%5D%0A%20%20I3%20--%3E%20P4%5B%22%E8%B7%AF%E5%BE%84%204%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">路径数按指数长：20 个独立判断就是 2 的 20 次方，约 105 万条路径；50 个判断已超过千万亿。「循环与状态空间」的税在工程上必须靠剪枝、合并与限深来压，否则求解器先饿死。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写破解某二进制保护的符号执行菜谱。静态污点下一课。</p><p><span class="marginnote">常见误区：把「KLEE 跑完没报错」当成「程序没有漏洞」。它只保证扫过的路径在求解精度内无反例；没走到的路径（尤其依赖外部环境的那部分）保持沉默——这正是它与 fuzz、人工审计互补的原因。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>fuzz 不擅长 magic；符号执行解路径条件。</li><li>KLEE 在 LLVM 上生成测试。</li><li>路径爆炸与环境是边界。</li><li>下一课静态与污点。</li><li>出处：Cadar, Dunbar and Engler, OSDI 2008；King, 1976。</li></ul>',6))])}const _=d(B,[["render",u]])